void trooper_set_knockback(float *p, float a, float b) __asm__("FUN_L03_00250a78");
void trooper_set_knockback(float *p, float a, float b) {
    float root = square_root((b + b) * p[4]);
    float x = (root + root) / p[4];
    p[7] = root;
    p[6] = (a + a) / x;
    p[5] = (a + a) / (x * x);
}
